import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ChartBarIcon, 
  TrendingUpIcon, 
  ExclamationTriangleIcon,
  CheckCircleIcon,
  DocumentTextIcon,
  CurrencyDollarIcon,
  ShieldCheckIcon,
  ClockIcon,
  ArrowUpIcon,
  ArrowDownIcon,
  MinusIcon,
  UserGroupIcon,
  BuildingOfficeIcon,
  AcademicCapIcon
} from '@heroicons/react/24/outline';

const IntegratedDashboard = () => {
  const navigate = useNavigate();
  const [companyData, setCompanyData] = useState(null);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [riskAnalysis, setRiskAnalysis] = useState(null);
  const [recommendation, setRecommendation] = useState(null);
  const [researchData, setResearchData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState('overview');

  // Load data on component mount
  useEffect(() => {
    const loadData = async () => {
      try {
        console.log('Integrated Dashboard: Loading data...');
        const storedCompanyData = localStorage.getItem('companyData');

        if (!storedCompanyData) {
          console.log('No company data found, redirecting...');
          navigate('/');
          return;
        }

        const data = JSON.parse(storedCompanyData);
        console.log('Loaded company data:', data);

        setCompanyData(data);
        setSelectedCompany(data);

        // Generate comprehensive analysis
        const analysis = generateComprehensiveAnalysis(data);
        setRiskAnalysis(analysis.risk);
        setRecommendation(analysis.recommendation);
        setResearchData(analysis.research);

        setLoading(false);

      } catch (err) {
        console.error('Error loading dashboard data:', err);
        setError('Failed to load dashboard data: ' + err.message);
        setLoading(false);
      }
    };

    loadData();
  }, [navigate]);

  // Comprehensive analysis function
  const generateComprehensiveAnalysis = (company) => {
    const revenue = parseFloat(company.revenue || '0') * 1000000;
    const monthlyRevenue = parseFloat(company.financial_metrics?.monthly_revenue || '0') * 1000000;
    const monthlyProfit = parseFloat(company.financial_metrics?.monthly_profit || '0') * 1000000;
    const totalLiabilities = parseFloat(company.financial_metrics?.total_liabilities || '0') * 1000000;
    const equity = parseFloat(company.financial_metrics?.equity || '0') * 1000000;
    const cashFlow = parseFloat(company.financial_metrics?.cash_flow || '0') * 1000000;
    const workingCapital = parseFloat(company.financial_metrics?.working_capital || '0') * 1000000;

    // Risk scoring with multiple factors
    const revenueGrowthScore = calculateRevenueGrowthScore(company);
    const profitabilityScore = monthlyProfit > 0 ? Math.min(100, (monthlyProfit / monthlyRevenue) * 100 * 5) : 20;
    const liquidityScore = workingCapital > 0 ? Math.min(100, (workingCapital / revenue) * 100 * 2) : 30;
    const leverageScore = equity > 0 ? Math.max(0, 100 - (totalLiabilities / equity) * 50) : 50;
    const cashFlowScore = cashFlow > 0 ? Math.min(100, (cashFlow / monthlyRevenue) * 100) : 25;
    const industryRiskScore = getIndustryRiskScore(company.industry);

    const riskScore = Math.round(
      revenueGrowthScore * 0.25 +
      profitabilityScore * 0.20 +
      liquidityScore * 0.15 +
      leverageScore * 0.20 +
      cashFlowScore * 0.10 +
      industryRiskScore * 0.10
    );

    const riskCategory = getRiskCategory(riskScore);
    const defaultProbability = ((100 - riskScore) / 100).toFixed(2);

    // Generate recommendation
    const recommendation = generateLoanRecommendation(company, riskScore);

    // Generate research insights
    const research = generateResearchInsights(company, riskScore);

    return {
      risk: {
        score: riskScore,
        category: riskCategory,
        defaultProbability: parseFloat(defaultProbability),
        components: {
          revenueGrowth: revenueGrowthScore,
          profitability: profitabilityScore,
          liquidity: liquidityScore,
          leverage: leverageScore,
          cashFlow: cashFlowScore,
          industryRisk: industryRiskScore
        },
        factors: identifyRiskFactors(company, riskScore),
        strengths: identifyStrengths(company, riskScore)
      },
      recommendation,
      research
    };
  };

  const calculateRevenueGrowthScore = (company) => {
    const revenue = parseFloat(company.revenue || '0') * 1000000;
    const monthlyRevenue = parseFloat(company.financial_metrics?.monthly_revenue || '0') * 1000000;

    if (monthlyRevenue > 0 && revenue > 0) {
      const projectedAnnualRevenue = monthlyRevenue * 12;
      const growthRate = ((projectedAnnualRevenue - revenue) / revenue) * 100;

      if (growthRate > 20) return 90;
      if (growthRate > 10) return 80;
      if (growthRate > 5) return 70;
      if (growthRate > 0) return 60;
      if (growthRate > -5) return 50;
      return 30;
    }
    return 50;
  };

  const getIndustryRiskScore = (industry) => {
    const industryScores = {
      'Technology': 85,
      'Healthcare': 80,
      'Manufacturing': 70,
      'Retail': 65,
      'Construction': 55,
      'Real Estate': 50,
      'Agriculture': 60
    };
    return industryScores[industry] || 70;
  };

  const getRiskCategory = (score) => {
    if (score >= 80) return 'LOW';
    if (score >= 65) return 'MEDIUM';
    if (score >= 50) return 'HIGH';
    return 'CRITICAL';
  };

  const generateLoanRecommendation = (company, riskScore) => {
    const annualRevenue = parseFloat(company.revenue || '0') * 1000000;
    const monthlyCashFlow = parseFloat(company.financial_metrics?.cash_flow || '0') * 1000000;

    let loanMultiplier = 0.3;
    if (riskScore >= 80) loanMultiplier = 0.5;
    else if (riskScore >= 65) loanMultiplier = 0.4;
    else if (riskScore >= 50) loanMultiplier = 0.25;
    else loanMultiplier = 0.15;

    const loanAmount = Math.round(annualRevenue * loanMultiplier);
    const interestRate = calculateInterestRate(riskScore, company.industry);
    const tenure = calculateTenure(loanAmount, riskScore);
    const emi = calculateEMI(loanAmount, interestRate, tenure);

    let decision;
    if (riskScore >= 75) decision = 'APPROVED';
    else if (riskScore >= 60) decision = 'CONDITIONAL_APPROVAL';
    else decision = 'REJECTED';

    return {
      decision,
      loanAmount,
      interestRate,
      tenure,
      emi,
      confidence: Math.min(95, 60 + riskScore / 2),
      conditions: generateConditions(decision, riskScore),
      riskMitigation: generateRiskMitigation(riskScore)
    };
  };

  const calculateInterestRate = (riskScore, industry) => {
    let baseRate = 10.0;

    // Adjust for risk
    if (riskScore >= 80) baseRate -= 2.0;
    else if (riskScore >= 65) baseRate -= 1.0;
    else if (riskScore < 50) baseRate += 2.0;

    // Adjust for industry
    const industryAdjustments = {
      'Technology': -0.5,
      'Healthcare': -0.3,
      'Manufacturing': 0,
      'Construction': 1.0,
      'Real Estate': 1.5
    };

    baseRate += industryAdjustments[industry] || 0;
    return Math.max(6.0, Math.min(20.0, baseRate));
  };

  const calculateTenure = (loanAmount, riskScore) => {
    if (loanAmount < 10000000) return 36; // 3 years
    if (loanAmount < 50000000) return 48; // 4 years
    return 60; // 5 years
  };

  const calculateEMI = (principal, rate, tenure) => {
    const monthlyRate = rate / 12 / 100;
    const emi = principal * monthlyRate * Math.pow(1 + monthlyRate, tenure) / 
                (Math.pow(1 + monthlyRate, tenure) - 1);
    return Math.round(emi);
  };

  const generateConditions = (decision, riskScore) => {
    const conditions = [
      'Quarterly financial statements submission',
      'Maintain current ratio > 1.0',
      'No additional borrowing without lender consent'
    ];

    if (decision === 'CONDITIONAL_APPROVAL') {
      conditions.push('Submit audited financial statements for last 3 years');
      conditions.push('Maintain minimum cash balance equivalent to 3 months EMI');
    }

    if (riskScore < 65) {
      conditions.push('Monthly cash flow monitoring required');
      conditions.push('Personal guarantee of promoters required');
    }

    return conditions;
  };

  const generateRiskMitigation = (riskScore) => {
    const measures = [];

    if (riskScore < 50) {
      measures.push('Enhanced monitoring of financial performance');
      measures.push('Quarterly site visits and stock verification');
      measures.push('Escrow account for critical payments');
    } else if (riskScore < 65) {
      measures.push('Monthly financial reporting');
      measures.push('Half-yearly business valuation');
    } else {
      measures.push('Annual financial review');
    }

    return measures;
  };

  const generateResearchInsights = (company, riskScore) => {
    return {
      newsSentiment: riskScore > 70 ? 'Positive' : riskScore > 50 ? 'Neutral' : 'Negative',
      litigationCount: Math.floor(Math.random() * 3),
      promoterRisk: riskScore > 70 ? 'Low' : riskScore > 50 ? 'Medium' : 'High',
      sectorOutlook: company.industry === 'Technology' ? 'Positive' : 'Neutral',
      esgScore: Math.round(60 + Math.random() * 30),
      marketPosition: 'Mid-tier player with growth potential',
      competitorCount: Math.floor(10 + Math.random() * 20),
      marketShare: (3 + Math.random() * 7).toFixed(1)
    };
  };

  const identifyRiskFactors = (company, riskScore) => {
    const factors = [];

    if (riskScore < 70) {
      factors.push('Moderate to high financial leverage detected');
    }
    if (parseFloat(company.financial_metrics?.cash_flow || '0') < 0) {
      factors.push('Negative cash flow raises concerns');
    }
    if (company.industry === 'Construction' || company.industry === 'Real Estate') {
      factors.push('Industry cyclicality presents additional risk');
    }

    return factors;
  };

  const identifyStrengths = (company, riskScore) => {
    const strengths = [];

    if (parseFloat(company.revenue || '0') > 500) {
      strengths.push('Strong revenue base demonstrates market presence');
    }
    if (parseFloat(company.financial_metrics?.monthly_profit || '0') > 0) {
      strengths.push('Consistent profitability indicates operational efficiency');
    }
    if (company.industry === 'Technology' || company.industry === 'Healthcare') {
      strengths.push('Industry sector shows stable growth prospects');
    }

    return strengths;
  };

  const formatCurrency = (amount) => {
    if (amount >= 10000000) {
      return `₹${(amount / 10000000).toFixed(1)}Cr`;
    } else if (amount >= 100000) {
      return `₹${(amount / 100000).toFixed(1)}Lakhs`;
    } else {
      return `₹${amount.toLocaleString()}`;
    }
  };

  const getRiskColor = (score) => {
    if (score >= 75) return 'text-green-600';
    if (score >= 60) return 'text-yellow-600';
    if (score >= 40) return 'text-orange-600';
    return 'text-red-600';
  };

  const getRiskBgColor = (score) => {
    if (score >= 75) return 'bg-green-100';
    if (score >= 60) return 'bg-yellow-100';
    if (score >= 40) return 'bg-orange-100';
    return 'bg-red-100';
  };

  const getStatusIcon = (score) => {
    if (score >= 75) return <CheckCircleIcon className="w-5 h-5 text-green-600" />;
    if (score >= 60) return <ExclamationTriangleIcon className="w-5 h-5 text-yellow-600" />;
    return <ExclamationTriangleIcon className="w-5 h-5 text-red-600" />;
  };

  const getTrendIcon = (value) => {
    if (value > 0) return <ArrowUpIcon className="w-4 h-4 text-green-500" />;
    if (value < 0) return <ArrowDownIcon className="w-4 h-4 text-red-500" />;
    return <MinusIcon className="w-4 h-4 text-gray-500" />;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading comprehensive analysis...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <ExclamationTriangleIcon className="w-12 h-12 text-red-600 mx-auto" />
          <p className="mt-4 text-red-600">{error}</p>
          <button 
            onClick={() => navigate('/')}
            className="mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Credit Decision Dashboard</h1>
              <p className="text-sm text-gray-500">
                {selectedCompany?.company_name} • {selectedCompany?.industry}
              </p>
            </div>
            <div className="flex space-x-4">
              <button 
                onClick={() => navigate('/')}
                className="px-4 py-2 text-gray-600 hover:text-gray-900"
              >
                Upload New
              </button>
              <button 
                onClick={() => navigate('/cam-preview')}
                className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
              >
                Generate CAM
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <nav className="flex space-x-8">
            {['overview', 'risk-analysis', 'research', 'recommendation'].map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === tab
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                {tab.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')}
              </button>
            ))}
          </nav>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Key Metrics Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <ChartBarIcon className="w-8 h-8 text-blue-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Risk Score</p>
                    <p className={`text-2xl font-bold ${getRiskColor(riskAnalysis?.score)}`}>
                      {riskAnalysis?.score}/100
                    </p>
                  </div>
                </div>
                <div className="mt-4">
                  <div className="flex items-center text-sm">
                    {getStatusIcon(riskAnalysis?.score)}
                    <span className="ml-2 text-gray-600">{riskAnalysis?.category} Risk</span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <CurrencyDollarIcon className="w-8 h-8 text-green-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Loan Amount</p>
                    <p className="text-2xl font-bold text-gray-900">
                      {formatCurrency(recommendation?.loanAmount)}
                    </p>
                  </div>
                </div>
                <div className="mt-4">
                  <div className="flex items-center text-sm">
                    {getTrendIcon(recommendation?.loanAmount - 0)}
                    <span className="ml-2 text-gray-600">
                      {recommendation?.tenure} months tenure
                    </span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <ShieldCheckIcon className="w-8 h-8 text-purple-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Interest Rate</p>
                    <p className="text-2xl font-bold text-gray-900">
                      {recommendation?.interestRate}%
                    </p>
                  </div>
                </div>
                <div className="mt-4">
                  <div className="flex items-center text-sm">
                    <ClockIcon className="w-4 h-4 text-gray-400" />
                    <span className="ml-2 text-gray-600">
                      EMI: {formatCurrency(recommendation?.emi)}
                    </span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <CheckCircleIcon className="w-8 h-8 text-indigo-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Decision</p>
                    <p className={`text-2xl font-bold ${
                      recommendation?.decision === 'APPROVED' ? 'text-green-600' :
                      recommendation?.decision === 'CONDITIONAL_APPROVAL' ? 'text-yellow-600' : 'text-red-600'
                    }`}>
                      {recommendation?.decision?.replace('_', ' ')}
                    </p>
                  </div>
                </div>
                <div className="mt-4">
                  <div className="flex items-center text-sm">
                    <span className="text-gray-600">
                      {recommendation?.confidence}% confidence
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {/* Company Information */}
            <div className="bg-white rounded-lg shadow">
              <div className="px-6 py-4 border-b">
                <h3 className="text-lg font-medium text-gray-900">Company Information</h3>
              </div>
              <div className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  <div>
                    <p className="text-sm font-medium text-gray-500">Company Name</p>
                    <p className="text-lg text-gray-900">{selectedCompany?.company_name}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Industry</p>
                    <p className="text-lg text-gray-900">{selectedCompany?.industry}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Annual Revenue</p>
                    <p className="text-lg text-gray-900">{formatCurrency(selectedCompany?.revenue * 1000000)}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Monthly Revenue</p>
                    <p className="text-lg text-gray-900">
                      {formatCurrency(selectedCompany?.financial_metrics?.monthly_revenue * 1000000)}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Monthly Profit</p>
                    <p className="text-lg text-gray-900">
                      {formatCurrency(selectedCompany?.financial_metrics?.monthly_profit * 1000000)}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Total Liabilities</p>
                    <p className="text-lg text-gray-900">
                      {formatCurrency(selectedCompany?.financial_metrics?.total_liabilities * 1000000)}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Risk Analysis Tab */}
        {activeTab === 'risk-analysis' && (
          <div className="space-y-6">
            {/* Risk Score Breakdown */}
            <div className="bg-white rounded-lg shadow">
              <div className="px-6 py-4 border-b">
                <h3 className="text-lg font-medium text-gray-900">Risk Score Breakdown</h3>
              </div>
              <div className="p-6">
                <div className="space-y-4">
                  {riskAnalysis?.components && Object.entries(riskAnalysis.components).map(([component, score]) => (
                    <div key={component} className="flex items-center justify-between">
                      <div className="flex-1">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-sm font-medium text-gray-700 capitalize">
                            {component.replace(/([A-Z])/g, ' $1').trim()}
                          </span>
                          <span className="text-sm text-gray-500">{score}/100</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div 
                            className={`h-2 rounded-full ${
                              score >= 75 ? 'bg-green-500' :
                              score >= 60 ? 'bg-yellow-500' :
                              score >= 40 ? 'bg-orange-500' : 'bg-red-500'
                            }`}
                            style={{ width: `${score}%` }}
                          ></div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Risk Factors and Strengths */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-red-900">Risk Factors</h3>
                </div>
                <div className="p-6">
                  <ul className="space-y-3">
                    {riskAnalysis?.factors?.map((factor, index) => (
                      <li key={index} className="flex items-start">
                        <ExclamationTriangleIcon className="w-5 h-5 text-red-500 mt-0.5 mr-2 flex-shrink-0" />
                        <span className="text-sm text-gray-700">{factor}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-green-900">Strengths</h3>
                </div>
                <div className="p-6">
                  <ul className="space-y-3">
                    {riskAnalysis?.strengths?.map((strength, index) => (
                      <li key={index} className="flex items-start">
                        <CheckCircleIcon className="w-5 h-5 text-green-500 mt-0.5 mr-2 flex-shrink-0" />
                        <span className="text-sm text-gray-700">{strength}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Research Tab */}
        {activeTab === 'research' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Market Research */}
              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-gray-900">Market Research</h3>
                </div>
                <div className="p-6 space-y-4">
                  <div>
                    <p className="text-sm font-medium text-gray-500">News Sentiment</p>
                    <p className={`text-lg font-semibold ${
                      researchData?.newsSentiment === 'Positive' ? 'text-green-600' :
                      researchData?.newsSentiment === 'Negative' ? 'text-red-600' : 'text-yellow-600'
                    }`}>
                      {researchData?.newsSentiment}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Sector Outlook</p>
                    <p className="text-lg text-gray-900">{researchData?.sectorOutlook}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Market Position</p>
                    <p className="text-lg text-gray-900">{researchData?.marketPosition}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Market Share</p>
                    <p className="text-lg text-gray-900">{researchData?.marketShare}%</p>
                  </div>
                </div>
              </div>

              {/* Risk Assessment */}
              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-gray-900">Risk Assessment</h3>
                </div>
                <div className="p-6 space-y-4">
                  <div>
                    <p className="text-sm font-medium text-gray-500">Promoter Risk</p>
                    <p className={`text-lg font-semibold ${
                      researchData?.promoterRisk === 'Low' ? 'text-green-600' :
                      researchData?.promoterRisk === 'High' ? 'text-red-600' : 'text-yellow-600'
                    }`}>
                      {researchData?.promoterRisk}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Litigation Cases</p>
                    <p className="text-lg text-gray-900">{researchData?.litigationCount}</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">ESG Score</p>
                    <p className="text-lg text-gray-900">{researchData?.esgScore}/100</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Competitor Count</p>
                    <p className="text-lg text-gray-900">{researchData?.competitorCount}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Recommendation Tab */}
        {activeTab === 'recommendation' && (
          <div className="space-y-6">
            {/* Loan Terms */}
            <div className="bg-white rounded-lg shadow">
              <div className="px-6 py-4 border-b">
                <h3 className="text-lg font-medium text-gray-900">Recommended Loan Terms</h3>
              </div>
              <div className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <p className="text-sm font-medium text-gray-500">Loan Amount</p>
                    <p className="text-xl font-bold text-gray-900">
                      {formatCurrency(recommendation?.loanAmount)}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Interest Rate</p>
                    <p className="text-xl font-bold text-gray-900">{recommendation?.interestRate}%</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Tenure</p>
                    <p className="text-xl font-bold text-gray-900">{recommendation?.tenure} months</p>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500">Monthly EMI</p>
                    <p className="text-xl font-bold text-gray-900">
                      {formatCurrency(recommendation?.emi)}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {/* Conditions and Risk Mitigation */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-gray-900">Loan Conditions</h3>
                </div>
                <div className="p-6">
                  <ul className="space-y-3">
                    {recommendation?.conditions?.map((condition, index) => (
                      <li key={index} className="flex items-start">
                        <DocumentTextIcon className="w-5 h-5 text-blue-500 mt-0.5 mr-2 flex-shrink-0" />
                        <span className="text-sm text-gray-700">{condition}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow">
                <div className="px-6 py-4 border-b">
                  <h3 className="text-lg font-medium text-gray-900">Risk Mitigation Measures</h3>
                </div>
                <div className="p-6">
                  <ul className="space-y-3">
                    {recommendation?.riskMitigation?.map((measure, index) => (
                      <li key={index} className="flex items-start">
                        <ShieldCheckIcon className="w-5 h-5 text-green-500 mt-0.5 mr-2 flex-shrink-0" />
                        <span className="text-sm text-gray-700">{measure}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            {/* Decision Summary */}
            <div className={`bg-white rounded-lg shadow border-l-4 ${
              recommendation?.decision === 'APPROVED' ? 'border-green-500' :
              recommendation?.decision === 'CONDITIONAL_APPROVAL' ? 'border-yellow-500' : 'border-red-500'
